const heroOf=s=>HEROES.find(h=>h.id===s.hero)||HEROES[0];
const HERO_START17={kruglov:0,severova:0,gromov:0,voronov:2,astra:4,svetlov:1,malyshev:1,vera:2};
function moveCost(s,to){const at=s.regions[s.heroAt];if(to===s.heroAt)return {why:'Герой уже здесь'};if(!at.nb.includes(to))return {why:'Только на соседний материк'};
  if(s.freeMove>0)return {free:true};if(s.ap<1)return {why:'Нет действий'};return {ap:1};}
function moveHero(s,to){if(s.over||s.event)return {ok:false};const c=moveCost(s,to);if(c.why)return {ok:false,msg:c.why};
  if(c.free)s.freeMove--;else s.ap--;const from=s.heroAt;s.heroAt=to;log(s,`${heroOf(s).name}: переход «${s.regions[from].name}» → «${s.regions[to].name}»`,'act');return {ok:true,from};}

/* ---------- geography: regions are continents on a 3D globe ---------- */
// continent ids: 0 Западная Европа, 8 Восточная Европа, 1 Северная Азия, 2 Южная и Восточная Азия, 3 Африка, 4 Северная Америка, 5 Южная Америка, 6 Австралия и Океания, 7 Антарктида
function contOf(lat,lon){
  if(lat<-60)return 7;
  if(lon>=-92&&lon<=-30&&lat<13)return 5;
  if(lon<-25||(lon<-10&&lat>59))return 4;
  if(lon>110&&lat<-10||lon>128&&lat<0&&lat>-50)return 6;
  if(lat>=36&&lon>=-25&&lon<60&&!(lat<42&&lon>26)){return lon<25?0:8;}
  if(lon>=-20&&lon<=52&&lat<37.5&&!(lat>12&&lon>33))return 3;
  return lat>=48||(lat>=44&&lon>60&&lon<120)?1:2;
}
const CADJ=[[0,8],[0,3],[8,1],[8,2],[0,2],[1,2],[1,4],[2,3],[2,6],[4,5],[5,7],[6,7],[3,5]];
const GROUPS={8:[[0,8],[1],[2],[3],[4],[5],[6],[7]],7:[[0,8],[1],[2],[3],[4],[5],[6]],6:[[0,8],[1,2],[3],[4],[5],[6]],5:[[0,8],[1,2],[3],[4,5],[6]]};
const ANCH={'0,8':[50,15],'1':[62,100],'2':[26,98],'1,2':[45,92],'3':[4,20],'4':[47,-100],'5':[-14,-60],'4,5':[15,-85],'6':[-25,134],'7':[-80,30]};
const HUMAN_GEO=[{c:[8],at:[55.75,37.62]},{c:[],at:[55.92,37.70],pt:1},{c:[0],at:[46.2,6.15]},{c:[5],at:[-27.07,-70.82]},{c:[1,2],at:[55.03,82.92]},{c:[],at:[40,-35],pt:1},{c:[],at:[-30,-88],pt:1},{c:[7],at:[-82.3,45.2]}];
const HUMAN_EDGES=[[0,1],[0,2],[0,4],[1,2],[1,4],[2,5],[3,5],[3,6],[5,6],[6,7],[3,7]];
function geoLayout(C){
  if(C.k==='human')return {geo:HUMAN_GEO.map(g=>({cont:g.c,lat:g.at[0],lon:g.at[1],pt:!!g.pt})),edges:HUMAN_EDGES};
  const G=GROUPS[C.regions];const geo=G.map(g=>{const a=ANCH[g.join(',')];return {cont:g,lat:a[0],lon:a[1],pt:false};});
  const edges=[];for(let i=0;i<G.length;i++)for(let j=i+1;j<G.length;j++)if(CADJ.some(([a,b])=>G[i].includes(a)&&G[j].includes(b)||G[i].includes(b)&&G[j].includes(a)))edges.push([i,j]);
  return {geo,edges};
}
const COASTAL=[2,4,5,6];
function lawsOpen(lvl){/* law order of unlock across civs 1..7 */const order=[4,1,2,3,5,6,7];return order.slice(0,Math.min(7,lvl));}
const has=(s,law)=>s.laws.includes(law);

function newGame(lvl,legacy,seed,hero){
  const C=CIVS[lvl-1];const rng=mkRng(seed||(Date.now()%1e9));
  const n=C.regions;const GL=geoLayout(C);let edges=GL.edges;
  if(C.k==='split')edges=edges.filter(([a,b])=>{const g=i=>[4,5,7].includes(i)?1:0;return g(a)===g(b);});
  const regions=[];
  for(let i=0;i<n;i++)regions.push({id:i,name:C.names[i],x:SLOTS[i][0],y:SLOTS[i][1],cont:GL.geo[i].cont,lat:GL.geo[i].lat,lon:GL.geo[i].lon,pt:GL.geo[i].pt,coast:GL.geo[i].cont.some(c=>COASTAL.includes(c)),pop:Math.round(65+rng()*30),fear:Math.round(14+rng()*16+lvl*.9),love:Math.round(14+rng()*14),b:{},nb:[]});
  for(const [a,b] of edges){regions[a].nb.push(b);regions[b].nb.push(a);}
  const laws=lawsOpen(lvl);
  const lg=laws.includes(7)?Math.min(legacy||0,12):0;
  const s={lvl,civ:C,rng,epoch:1,maxEpoch:C.epochs,apMax:C.k==='tyrant'?2:3,ap:0,light:6+lg,know:2,memory:Math.floor(lg/2),goal:Math.round(C.goal*goalMul(lvl)),dAdd:driftAdd(lvl),
    hunger:15,souls:0,lost:0,freed:0,corrections:laws.includes(5)?1:0,regions,laws,log:[],over:null,ai:null,
    initPop:regions.reduce((a,r)=>a+r.pop,0),sats:3,one:0,flood:0,event:null,usedEvents:[],legacyApplied:lg,stats:{gipnos:0,dreams:0}};
  s.hero=hero||'kruglov';s.heroEpoch=0;s.heroUsed=0;s.freeMove=1;
  s.heroAt=C.k==='human'?HERO_START17[s.hero]||0:[...regions].sort((a,b)=>b.fear-a.fear)[0].id;
  if(s.hero==='vera'){s.light+=8;s.know+=4;}
  s.ap=s.apMax;s.timed=typeof window!=='undefined';
  if(C.k==='human'){
    // Particular canon setup
    const R=s.regions;R[1].b.mirror=1;R[1].fear=48;R[2].b.lab=1;R[2].b.core=1;R[0].b.core=1;R[4].love=30;R[5].fear=22;R[6].fear=40;R[7].fear=44;
    s.ai='oneiros';s.hunger=35;s.know=6;
  }
  return s;
}
const avg=(s,f)=>s.regions.reduce((a,r)=>a+f(r),0)/s.regions.length;
const avgFear=s=>avg(s,r=>r.fear);const avgLove=s=>avg(s,r=>r.love);
const totalPop=s=>s.regions.reduce((a,r)=>a+r.pop,0);
function log(s,t,kind){s.log.unshift({t,kind,e:s.epoch});if(s.log.length>40)s.log.pop();}
function kill(s,r,d){d=Math.min(r.pop,Math.round(d));if(d<=0)return 0;r.pop-=d;
  if(r.b.mirror){s.souls+=d;}else s.lost+=d;return d;}

