  const spreadAt=(k==='plague'||k==='self')?50:60;
  const pressure=s.hunger/25;
  const oneMult=k==='human'?ONEIROS_STAGES[s.one].mult:1;
  // flaws before drift
  if(k==='aggr'||k==='self'){const r=pick(s,R);r.fear+=k==='self'?9:12;if(r.nb.length){const n2=R[pick(s,r.nb)];n2.fear+=k==='self'?5:7;}notes.push(`Вспышка ярости: «${r.name}»`);}
  if(k==='tech'||k==='self'){for(const r of R)if(r.b.lab&&rng()<.18){r.fear+=24;kill(s,r,6);notes.push(`Авария в лаборатории: «${r.name}»`);}}
  if(k==='flood'){s.flood++;if(s.flood%3===0){for(const r of R.filter(r=>r.coast)){kill(s,r,14);r.fear+=12;}notes.push('Потоп накрыл побережья');}}
